INSERT INTO missions ("id", "name", "description", "environment", "status", "startDate", "endDate", "patchUrl", "createdById", "createdAt", "updatedAt", "deletedAt") VALUES
  ('mission-01', 'Artemis II — Crewed Lunar Free-Return', '9-day crewed flight test aboard SLS Block 1 and Orion (Integrity) with Reid Wiseman, Victor Glover, Christina Koch, and Jeremy Hansen reaching 6,545 km above the lunar far side.', 'SPACECRAFT', 'IN_PROGRESS', (timezone('utc', now()) - interval '345600000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), (timezone('utc', now()) - interval '-169 milliseconds'), (timezone('utc', now()) - interval '-169 milliseconds'), NULL),
  ('mission-02', 'ISS Expedition 72 — Low Earth Orbit', 'Orbital science aboard the International Space Station at 408–420 km LEO, 51.6° inclination, and 7.66 km/s (~90 min orbital period) with Crew Dragon and Soyuz MS crew rotations.', 'STATION', 'IN_PROGRESS', (timezone('utc', now()) - interval '10800000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), (timezone('utc', now()) - interval '-172 milliseconds'), (timezone('utc', now()) - interval '-172 milliseconds'), NULL),
  ('mission-03', 'Lunar Reconnaissance Orbiter (LRO)', 'Launched June 18, 2009 on Atlas V 401 into a 50 km circular lunar polar mapping orbit over Shackleton Crater and the lunar south pole.', 'LUNAR_BASE', 'IN_PROGRESS', (timezone('utc', now()) - interval '18000000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), (timezone('utc', now()) - interval '-174 milliseconds'), (timezone('utc', now()) - interval '-174 milliseconds'), NULL),
  ('mission-04', 'Mars 2020 Perseverance — Jezero Crater', 'Launched July 30, 2020 on ULA Atlas V 541 on a 202-day interplanetary cruise to Jezero Crater, Mars, monitoring deep-space GCR/SPE radiation exposure.', 'MARS_BASE', 'IN_PROGRESS', (timezone('utc', now()) - interval '345600000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), (timezone('utc', now()) - interval '-176 milliseconds'), (timezone('utc', now()) - interval '-176 milliseconds'), NULL),
  ('mission-05', 'Europa Clipper — Jupiter Orbit Cruise', 'Launched Oct 14, 2024 on SpaceX Falcon Heavy on a 5.5-year trajectory with Mars and Earth gravity assists toward Jupiter arrival in April 2030.', 'SPACECRAFT', 'IN_PROGRESS', (timezone('utc', now()) - interval '432000000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), (timezone('utc', now()) - interval '-178 milliseconds'), (timezone('utc', now()) - interval '-178 milliseconds'), NULL),
  ('mission-06', 'Parker Solar Probe — Venus Gravity Assist', 'Launched Aug 12, 2018 on ULA Delta IV Heavy executing seven Venus gravity-assist flybys to tighten its inner-system solar perihelion.', 'SPACECRAFT', 'IN_PROGRESS', (timezone('utc', now()) - interval '172800000 milliseconds'), NULL, NULL, (SELECT id FROM users WHERE email = 'elena.rodriguez@nasa.gov'), (timezone('utc', now()) - interval '-179 milliseconds'), (timezone('utc', now()) - interval '-179 milliseconds'), NULL)
